// Exact delivery-plinth submesh from the canonical 02E facility. This is used only
// as a late occluder for the tractor stream; it does not duplicate or alter the
// approved outpost geometry.
const swampRelayDeliveryPlinthMesh=(()=>{
  const ids=[251,252,253,254,255,256,257,258],map=new Map(ids.map((id,i)=>[id,i]));
  return{
    v:ids.map(id=>swampRelayOutpostMesh.v[id]),
    e:(swampRelayOutpostMesh.e||[]).filter(([a,b])=>map.has(a)&&map.has(b)).map(([a,b])=>[map.get(a),map.get(b)]),
    faces:(swampRelayOutpostMesh.faces||[]).filter(face=>face.every(id=>map.has(id))).map(face=>face.map(id=>map.get(id)))
  };
})();


// The communications mast is part of the approved 02E mesh, but its lattice
// linework is red while the prefab buildings remain white. Keep the canonical
// vertices/faces untouched; only separate the tower edges for colour rendering.
const swampRelayCommsTowerVertexSet=new Set(Array.from({length:25},(_,i)=>226+i));
const swampRelayCommsTowerEdges=(swampRelayOutpostMesh.e||[]).filter(([a,b])=>swampRelayCommsTowerVertexSet.has(a)&&swampRelayCommsTowerVertexSet.has(b));
const swampRelayOutpostBodyMesh=Object.assign({},swampRelayOutpostMesh,{e:(swampRelayOutpostMesh.e||[]).filter(([a,b])=>!(swampRelayCommsTowerVertexSet.has(a)&&swampRelayCommsTowerVertexSet.has(b)))});

function drawSwampRelayCommsTower(obj){
  if(!obj)return;
  const mesh=swampRelayOutpostMesh,mx=obj.mx||1,my=obj.my||1,mz=obj.mz||1;
  const world=mesh.v.map(v=>{const q=rotate([v[0]*obj.s*mx,v[1]*obj.s*my,v[2]*obj.s*mz],obj.rot);return[q[0]+obj.x,q[1]+obj.y,q[2]+obj.z]});
  const cam=world.map(camPoint),pts=cam.map(projectCam),tris=[];
  for(const face of mesh.faces||[]){for(let i=1;i<face.length-1;i++){const ids=[face[0],face[i],face[i+1]],pp=ids.map(j=>pts[j]),cc=ids.map(j=>cam[j]);if(pp.every(Boolean)&&cc.every(q=>q[2]>.18))tris.push({ids,p:pp,c:cc})}}
  for(const edge of swampRelayCommsTowerEdges){const ia=edge[0],ib=edge[1],A=cam[ia],B=cam[ib];if(!A||!B)continue;
    const pieces=7;for(let k=0;k<pieces;k++){const t0=k/pieces,t1=(k+1)/pieces,tm=(t0+t1)*.5;
      const q0=[lerp(A[0],B[0],t0),lerp(A[1],B[1],t0),lerp(A[2],B[2],t0)],q1=[lerp(A[0],B[0],t1),lerp(A[1],B[1],t1),lerp(A[2],B[2],t1)],qm=[lerp(A[0],B[0],tm),lerp(A[1],B[1],tm),lerp(A[2],B[2],tm)];
      const p0=projectCam(q0),p1=projectCam(q1),pm=projectCam(qm);if(!p0||!p1||!pm)continue;let hidden=false;
      for(const tr of tris){if(tr.ids.includes(ia)&&tr.ids.includes(ib))continue;const bc=pointInTri(pm.x,pm.y,tr.p[0],tr.p[1],tr.p[2]);if(!bc)continue;const invz=bc[0]/tr.c[0][2]+bc[1]/tr.c[1][2]+bc[2]/tr.c[2][2];if(invz>0&&1/invz<qm[2]-.035){hidden=true;break}}
      if(!hidden)line(p0.x,p0.y,p1.x,p1.y,C.r,VECTOR_LINE_WIDTH,.98)
    }
  }
}

